1	package org.springframework.samples.petclinic.util;
2	
3	import java.util.Map;
4	
5	/**
6	 * Converts a raw, user-supplied postal address into a canonical form for storage.
7	 *
8	 * <p>The rules are:
9	 * <ul>
10	 *     <li>the value is trimmed and every run of whitespace is collapsed to a single space;</li>
11	 *     <li>the result is upper-cased;</li>
12	 *     <li>common street-type abbreviations are expanded as whole tokens
13	 *         ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}).</li>
14	 * </ul>
15	 *
16	 * <p>So {@code "  12  main  st "} becomes {@code "12 MAIN STREET"} and {@code "7 elm ave"}
17	 * becomes {@code "7 ELM AVENUE"}. The normalization is idempotent: feeding it an already
18	 * normalized value returns that same value.
19	 */
20	public final class AddressNormalizer {
21	
22	    /**
23	     * Known street-type abbreviations expanded during normalization. Keyed by the upper-cased
24	     * token, so the lookup runs after the address has been upper-cased.
25	     */
26	    private static final Map<String, String> STREET_ABBREVIATIONS = Map.of(
27	        "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
28	
29	    private AddressNormalizer() {
30	    }
31	
32	    /**
33	     * Normalize a raw postal address to its canonical form, or return {@code null} when the
34	     * input is {@code null}. A value that is blank once trimmed normalizes to an empty string.
35	     */
36	    public static String normalize(String raw) {
37	        if (raw == null) {
38	            return null;
39	        }
40	        String collapsed = raw.trim().replaceAll("\\s+", " ").toUpperCase();
41	        if (collapsed.isEmpty()) {
42	            return collapsed;
43	        }
44	        String[] tokens = collapsed.split(" ");
45	        StringBuilder sb = new StringBuilder(collapsed.length());
46	        for (int i = 0; i < tokens.length; i++) {
47	            if (i > 0) {
48	                sb.append(' ');
49	            }
50	            sb.append(STREET_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
51	        }
52	        return sb.toString();
53	    }
54	}
