260	    /**
261	     * The upper-cased first three letters of {@code value} (fewer if it is shorter), treating a
262	     * {@code null} value as empty. This is the shared rule behind both the CITY3 and LAST3
263	     * segments of a {@code customerCode}.
264	     */
265	    private static String prefix3(String value) {
266	        String s = value == null ? "" : value;
267	        return s.substring(0, Math.min(3, s.length())).toUpperCase();
