278	    public boolean isHouseholdInUse(String lastName, String address) throws DataAccessException {
279	        String normalizedLastName = normalizeForComparison(lastName);
280	        String normalizedAddress = normalizeForComparison(address);
281	        if (normalizedLastName == null || normalizedAddress == null) {
282	            return false;
283	        }
284	        return ownerRepository.findAll().stream()
285	            .anyMatch(existing -> inHousehold(existing, normalizedLastName, normalizedAddress));
286	    }
