288	    /**
289	     * Canonicalize a free-text value for equality comparison: trim, collapse every run of
290	     * whitespace to a single space and lower-case the result, so values that differ only in
291	     * letter case or incidental whitespace are treated as equal. Shared by the household
292	     * (last name / address) and per-city matching rules.
293	     */
294	    private String normalizeForComparison(String value) {
295	        if (value == null) {
296	            return null;
297	        }
298	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
299	    }
