301	    /**
302	     * Single definition of household membership: an owner belongs to the household identified by
303	     * the given already-normalized last name and address when its own normalized last name and
304	     * address match. Keeping this in one place means the household-equality rule is changed once.
305	     */
306	    private boolean inHousehold(Owner existing, String normalizedLastName, String normalizedAddress) {
307	        return normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
308	            && normalizedAddress.equals(normalizeForComparison(existing.getAddress()));
309	    }
