319	    @Override
320	    @Transactional
321	    public String assignHousehold(Owner owner) throws DataAccessException {
322	        String householdId = generateHouseholdId(owner.getLastName(), owner.getAddress());
323	        owner.setHouseholdId(householdId);
324	        String normalizedLastName = normalizeForComparison(owner.getLastName());
325	        String normalizedAddress = normalizeForComparison(owner.getAddress());
326	        if (normalizedLastName != null && normalizedAddress != null) {
327	            // Back-fill existing members of the household so the joining owner and the
328	            // owner(s) already at the address share the same stable identifier.
329	            for (Owner existing : ownerRepository.findAll()) {
330	                if (existing.getHouseholdId() == null
331	                    && inHousehold(existing, normalizedLastName, normalizedAddress)) {
332	                    existing.setHouseholdId(householdId);
333	                    ownerRepository.save(existing);
334	                }
335	            }
336	        }
337	        return householdId;
338	    }
339	
340	    /**
341	     * Derive a stable household identifier from the normalized last name and address, so that
342	     * every owner sharing a household (same last name and address, compared case-insensitively
343	     * with internal whitespace collapsed) maps to the same value. The identifier is the first
344	     * eight upper-case hex characters of the SHA-256 of {@code <lastName>|<address>}, prefixed
345	     * with {@code 'H-'} (e.g. {@code H-3F5A9C2E}).
346	     */
347	    private String generateHouseholdId(String lastName, String address) {
348	        String key = normalizeForComparison(lastName) + "|" + normalizeForComparison(address);
349	        try {
350	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
351	            StringBuilder sb = new StringBuilder("H-");
352	            for (int i = 0; i < 4; i++) {
353	                sb.append(String.format("%02X", digest[i]));
354	            }
355	            return sb.toString();
356	        }
357	        catch (NoSuchAlgorithmException e) {
358	            throw new IllegalStateException("SHA-256 not available", e);
359	        }
360	    }
