29	    @Mapping(target = "membershipLevel", expression = "java(formatMembershipLevel(owner))")
30	    @Mapping(target = "locality", expression = "java(formatLocality(owner))")
31	    @Mapping(target = "bulkSignupWarning", expression = "java(formatBulkSignupWarning(owner))")
32	    @Mapping(target = "contactPreference", expression = "java(formatContactPreference(owner))")
33	    OwnerDto toOwnerDto(Owner owner);
34	
35	    /**
36	     * Derive an owner's preferred contact channel from its stored contact details:
37	     * {@code "EMAIL"} when a (non-blank) email address is present, otherwise {@code "PHONE"}.
38	     */
39	    default String formatContactPreference(Owner owner) {
40	        if (owner == null) {
41	            return null;
42	        }
43	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
44	        return hasEmail ? "EMAIL" : "PHONE";
45	    }
46	
47	    /**
48	     * Resolve an owner's bulk-signup warning flag, coalescing a {@code null} stored value
49	     * (e.g. for owners created before the flag existed) to {@code false} so the response
50	     * always carries an explicit boolean.
51	     */
52	    default Boolean formatBulkSignupWarning(Owner owner) {
53	        if (owner == null) {
54	            return null;
55	        }
56	        return Boolean.TRUE.equals(owner.getBulkSignupWarning());
57	    }
58	
59	    /**
60	     * Known city-to-region mappings. Keyed by the exact city name, the canonical region
61	     * string is returned for a listed city and {@code "UNKNOWN"} for anything else.
62	     */
63	    Map<String, String> CITY_REGIONS = Map.of(
64	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
65	
66	    /**
67	     * Canonical region ranges keyed by region, each an inclusive 4-digit postcode range
68	     * {@code {low, high}}: NSW 2000-2099, VIC 3000-3099, QLD 4000-4099.
69	     */
70	    Map<String, int[]> REGION_RANGES = Map.of(
71	        "NSW", new int[] {2000, 2099},
72	        "VIC", new int[] {3000, 3099},
73	        "QLD", new int[] {4000, 4099});
74	
75	    /**
76	     * Derive an owner's locality, preferring the postcode: when the owner has a 4-digit
77	     * postcode that falls in a known region range ({@link #REGION_RANGES}), that region
78	     * is returned. Otherwise (the postcode is absent or in no known range) it falls back
79	     * to the fixed {@link #CITY_REGIONS} city-to-region table, returning the canonical
80	     * region string or {@code "UNKNOWN"} when the city is {@code null} or not listed.
81	     * This returns the same region for known cities but disambiguates cities that share
82	     * a name. Returns {@code null} only when the owner itself is {@code null}.
83	     */
84	    default String formatLocality(Owner owner) {
85	        if (owner == null) {
86	            return null;
87	        }
88	        String postcode = owner.getPostcode();
89	        if (postcode != null && postcode.matches("[0-9]{4}")) {
90	            int value = Integer.parseInt(postcode);
91	            for (Map.Entry<String, int[]> entry : REGION_RANGES.entrySet()) {
92	                int[] range = entry.getValue();
93	                if (value >= range[0] && value <= range[1]) {
94	                    return entry.getKey();
95	                }
96	            }
97	        }
98	        return CITY_REGIONS.getOrDefault(owner.getCity(), "UNKNOWN");
99	    }
100	
101	    /**
102	     * Determine an owner's membership level, a number from {@code 1} to {@code 3} assigned on
103	     * create. It starts at {@code 1}, gains {@code 1} when an email address is present, and gains
104	     * {@code 1} when the owner has no namesakes (its {@code namesakeCount} is {@code 0}), capped at
105	     * {@code 3}. A null or absent namesake count is treated as not being zero, so it contributes
106	     * nothing. Level {@code 4} is reserved for tenure.
107	     */
108	    default Integer formatMembershipLevel(Owner owner) {
109	        if (owner == null) {
110	            return null;
111	        }
112	        int level = 1;
113	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
114	        if (hasEmail) {
115	            level++;
116	        }
117	        boolean uniqueName = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
118	        if (uniqueName) {
119	            level++;
120	        }
121	        return Math.min(level, 3);
122	    }
123	
124	    /**
125	     * Compute an owner's check digit: a single Luhn check digit (0-9) over the digits
126	     * contained in the owner's {@code customerCode}. Non-digit characters (the city and
127	     * last-name segments) are ignored. Returns {@code null} when the owner or its customer
128	     * code is absent, since the digit cannot be derived without the code.
129	     */
130	    default Integer formatCheckDigit(Owner owner) {
131	        if (owner == null || owner.getCustomerCode() == null) {
132	            return null;
133	        }
134	        String code = owner.getCustomerCode();
135	        int sum = 0;
136	        boolean dbl = true;
137	        for (int i = code.length() - 1; i >= 0; i--) {
138	            char c = code.charAt(i);
139	            if (c < '0' || c > '9') {
140	                continue;
141	            }
142	            int d = c - '0';
143	            if (dbl) {
144	                d *= 2;
145	                if (d > 9) {
146	                    d -= 9;
147	                }
148	            }
149	            sum += d;
150	            dbl = !dbl;
151	        }
152	        return (10 - (sum % 10)) % 10;
153	    }
154	
155	    /**
156	     * Format an owner's membership number as {@code "<customerCode>-M<YY>"}, where {@code YY}
157	     * is the last two digits of the registration date year (e.g. {@code "TOW-SMI-0007-M26"}).
158	     * Returns {@code null} when either the customer code or registration date is absent, since
159	     * the number cannot be derived without both.
160	     */
161	    default String formatMembershipNumber(Owner owner) {
162	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
163	            return null;
164	        }
165	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
166	    }
167	
168	    /**
169	     * Format an owner's name as {@code "LastName, FirstName"} from the stored names.
170	     */
171	    default String formatDisplayName(Owner owner) {
172	        if (owner == null) {
173	            return null;
174	        }
175	        return owner.getLastName() + ", " + owner.getFirstName();
176	    }
177	
178	    /**
179	     * Format an owner's initials as the upper-cased first letters of the first and last
180	     * names, dot-separated with a trailing dot, e.g. {@code "J.S."}.
181	     */
182	    default String formatInitials(Owner owner) {
183	        if (owner == null) {
184	            return null;
185	        }
186	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
187	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
188	    }
