248	     * first three letters of the owner's city, a hyphen, the upper-cased first three letters of
249	     * the owner's last name, a hyphen, and a per-city 4-digit zero-padded sequence equal to one
250	     * more than the number of owners already registered in that city (e.g. {@code TOW-SMI-0007}).
251	     */
252	    private String generateCustomerCode(Owner owner) {
253	        String city = owner.getCity() == null ? "" : owner.getCity();
254	        int sequence = (int) ownerRepository.findAll().stream()
255	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
256	            .count() + 1;
257	        return String.format("%s-%s-%04d", prefix3(city), prefix3(owner.getLastName()), sequence);
