2	
3	import java.util.LinkedHashMap;
4	import java.util.Map;
5	
6	/**
7	 * Converts a raw, user-supplied telephone number into E.164 form.
8	 *
9	 * <p>The rules are:
10	 * <ul>
11	 *     <li>spaces, dashes and brackets are stripped;</li>
12	 *     <li>a leading {@code '+'} and country code are kept when present;</li>
13	 *     <li>otherwise country code {@code '+61'} is assumed and a single leading
14	 *         {@code '0'} is dropped from the national digits;</li>
15	 *     <li>the result must carry 8 to 15 digits after the {@code '+'};</li>
16	 *     <li>for a known country code the national number (the digits after the
17	 *         country code) must have the exact length that country requires:
18	 *         {@code '+61'} requires 9 national digits and {@code '+1'} requires 10.</li>
19	 * </ul>
20	 *
21	 * <p>So {@code "0412 345 678"} becomes {@code "+61412345678"} and
22	 * {@code "+64 21 123 456"} becomes {@code "+6421123456"}. The normalization is
23	 * idempotent: feeding it an already-E.164 value returns that same value.
24	 */
25	public final class E164Telephone {
26	
27	    private static final String DEFAULT_COUNTRY_CODE = "61";
28	
29	    /**
30	     * Known country codes mapped to the exact national-number length they require.
31	     * Ordered longest-prefix first so the country code is matched unambiguously.
32	     */
33	    private static final Map<String, Integer> NATIONAL_LENGTHS = new LinkedHashMap<>();
34	
35	    static {
36	        NATIONAL_LENGTHS.put("61", 9);
37	        NATIONAL_LENGTHS.put("1", 10);
38	    }
39	
40	    private E164Telephone() {
41	    }
42	
43	    /**
44	     * Normalize a raw telephone number to E.164 form, or return {@code null} when the
45	     * input is {@code null} or cannot form a valid E.164 number.
46	     */
47	    public static String normalize(String raw) {
48	        if (raw == null) {
49	            return null;
50	        }
51	        // strip spaces, dashes and brackets
52	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
53	        String digits;
54	        if (cleaned.startsWith("+")) {
55	            digits = cleaned.substring(1);
56	        } else {
57	            if (cleaned.startsWith("0")) {
58	                cleaned = cleaned.substring(1);
59	            }
60	            digits = DEFAULT_COUNTRY_CODE + cleaned;
61	        }
62	        if (!digits.matches("\\d{8,15}")) {
63	            return null;
64	        }
65	        for (Map.Entry<String, Integer> entry : NATIONAL_LENGTHS.entrySet()) {
66	            String countryCode = entry.getKey();
67	            if (digits.startsWith(countryCode)) {
68	                int nationalLength = digits.length() - countryCode.length();
69	                return nationalLength == entry.getValue() ? "+" + digits : null;
70	            }
71	        }
72	        return "+" + digits;
73	    }
74	
75	    /**
76	     * Whether the raw value can be converted to a valid E.164 number.
77	     */
78	    public static boolean isValid(String raw) {
79	        return normalize(raw) != null;
80	    }
81	}
