120	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
121	        HttpHeaders headers = new HttpHeaders();
122	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
123	        // The effective registration date (supplied, or the server date when omitted) must fall on
